window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d0eaca1fecf93878"]={"versions": [{"id": "FIG-d0eaca1fecf93878", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Diagramm / Feature-Baum (Feature-Oriented Domain Analysis / FODA-Notation gemäß AUTOSAR Feature Modeling Standard).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, R24-11). Das Diagramm dient der plattformübergreifenden Variabilitäts- und Anforderungsmodellierung. Es definiert die funktionale Dekomposition des übergeordneten Kommunikations-Features <code>IP</code> (<code>FO_TR_FEAT_00167</code>) in funktionale Teilaspekte für die Standard-Netzwerkkommunikation über Ethernet (Classic und Adaptive Platform).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzel-Feature (Parent Node):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00167</code> (<code>IP</code>): Zentrales Umbrella-Feature für den IP-basierten Kommunikationsstack.\n</li></ul>\n</li><li><strong>Dekompositions-Knoten (Child Nodes / Sub-Features):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00168</code> (<code>IP_V4</code>): IPv4-Netzwerkschicht (RFC 791, Adressierung, Fragmentierung, Routing).\n</li><li><code>FO_TR_FEAT_00170</code> (<code>IP_V6</code>): IPv6-Netzwerkschicht (RFC 8200, 128-Bit-Adressierung, Neighbor Discovery).\n</li><li><code>FO_TR_FEAT_00172</code> (<code>ICMP</code>): Internet Control Message Protocol (Fehlermeldungen, Diagnostik, ICMPv4/ICMPv6).\n</li><li><code>FO_TR_FEAT_00173</code> (<code>UDP</code>): User Datagram Protocol (RFC 768, verbindungsloser Transportdienst, z. B. Basis für SOME/IP oder DoIP).\n</li><li><code>FO_TR_FEAT_00174</code> (<code>TCP</code>): Transmission Control Protocol (RFC 9293, verbindungsorientierter, zuverlässiger Bytestrom).\n</li><li><code>FO_TR_FEAT_00176</code> (<code>IPSec</code>): IP Security (RFC 4301, Authentifizierung und Verschlüsselung auf Network Layer via AH/ESP).\n</li><li><code>FO_TR_FEAT_00177</code> (<code>DHCP</code>): Dynamic Host Configuration Protocol (automatische IP-Konfiguration / DHCPv4 / DHCPv6).\n</li></ul>\n</li><li><strong>Relationen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Beziehungstyp:</strong> Baumförmige 1:n-Dekomposition.\n</li><li><strong>Kanten-Semantik:</strong> Alle Kanten enden am Kindknoten mit einem <strong>ungefüllten Kreis (Hollow Circle)</strong>. Dies kennzeichnet normativ <strong>optionale Sub-Features</strong> (Kardinalität <code>[0..1]</code> je Zweig).\n</li><li><strong>Constraint-Ebene:</strong> Auf rein syntaktischer Ebene des Baums existieren keine zwingenden Exklusivitäten (kein XOR/OR-Bogen); semantisch gelten jedoch Protokollabhängigkeiten (z. B. zwingende Auswahl mindestens eines Network Layers <code>IP_V4</code> oder <code>IP_V6</code>; Abhängigkeit von <code>DHCP</code> von <code>UDP</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statische Variabilitätsarchitektur):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm beschreibt keinen Kontrollfluss, keine PDU-Routen und keine Laufzeit-Zustandsübergänge.\n</li><li>Es modelliert die funktionale Struktur zur Spezifikations-, Ableitungs- und Konfigurationszeit (Design-Time Variability).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- und Generierungszeit (BSW / Platform Stacks):</strong>\n<ul class=\"fig-list\"><li><strong>Classic Platform (CP):</strong> Die Selektion der Sub-Features steuert die BSW-Codegenerierung und Pre-Compile-Schalter des BSW-Moduls <code>TcpIp</code> (SWS_TCPIP) sowie übergeordneter Module (<code>SoAd</code>, <code>DoIP</code>, <code>Sd</code>). Nicht selektierte Features (z. B. <code>FO_TR_FEAT_00174</code> TCP bei reiner UDP-Broadcast-/SOME/IP-Nutzung oder <code>FO_TR_FEAT_00176</code> IPSec) werden über Schalter wie <code>TCPIP_TCP_ENABLED == STD_OFF</code> komplett aus dem Binary entfernt.\n</li><li><strong>Adaptive Platform (AP):</strong> Definiert Plattformanforderungen an den zugrundeliegenden POSIX-Kernel (z. B. Linux Network Subsystem, XFRM/IPSec-Support, Socket-Domänen <code>AF_INET</code>/<code>AF_INET6</code>) sowie System-Dienste (<code>systemd-networkd</code>, DHCP-Clients).\n</li></ul>\n</li><li><strong>Ressourcenallokation &amp; Safety/Security:</strong>\n<ul class=\"fig-list\"><li>Jedes optionale Feature bindet signifikant RAM/ROM (TCP-Send/Receive-Buffer, Reassembly-Buffer, IPSec-Security-Associations). Das Feature-Modell dient als normative Referenz zur Reduktion der Angriffsfläche (Attack Surface Reduction) und zur Einhaltung strenger Speichergrenzen im Steuergerät.\n</li></ul>\n</li><li><strong>Traceability:</strong>\n<ul class=\"fig-list\"><li>Die IDs (<code>FO_TR_FEAT_*</code>) sind bindende Tracing-Anker für Lastenhefte, Konformitätstests (Conformance Testing) und Release-Verifikationen gegen R24-11.\n</li></ul>\n</li></ul>"}, {"id": "FIG-c70e981e2269b518", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Diagramm / Feature-Baum (Feature-Oriented Domain Analysis / FODA-Notation gemäß AUTOSAR Feature Modeling Standard).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, R24-11). Das Diagramm dient der plattformübergreifenden Variabilitäts- und Anforderungsmodellierung. Es definiert die funktionale Dekomposition des übergeordneten Kommunikations-Features <code>IP</code> (<code>FO_TR_FEAT_00167</code>) in funktionale Teilaspekte für die Standard-Netzwerkkommunikation über Ethernet (Classic und Adaptive Platform).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzel-Feature (Parent Node):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00167</code> (<code>IP</code>): Zentrales Umbrella-Feature für den IP-basierten Kommunikationsstack.\n</li></ul>\n</li><li><strong>Dekompositions-Knoten (Child Nodes / Sub-Features):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00168</code> (<code>IP_V4</code>): IPv4-Netzwerkschicht (RFC 791, Adressierung, Fragmentierung, Routing).\n</li><li><code>FO_TR_FEAT_00170</code> (<code>IP_V6</code>): IPv6-Netzwerkschicht (RFC 8200, 128-Bit-Adressierung, Neighbor Discovery).\n</li><li><code>FO_TR_FEAT_00172</code> (<code>ICMP</code>): Internet Control Message Protocol (Fehlermeldungen, Diagnostik, ICMPv4/ICMPv6).\n</li><li><code>FO_TR_FEAT_00173</code> (<code>UDP</code>): User Datagram Protocol (RFC 768, verbindungsloser Transportdienst, z. B. Basis für SOME/IP oder DoIP).\n</li><li><code>FO_TR_FEAT_00174</code> (<code>TCP</code>): Transmission Control Protocol (RFC 9293, verbindungsorientierter, zuverlässiger Bytestrom).\n</li><li><code>FO_TR_FEAT_00176</code> (<code>IPSec</code>): IP Security (RFC 4301, Authentifizierung und Verschlüsselung auf Network Layer via AH/ESP).\n</li><li><code>FO_TR_FEAT_00177</code> (<code>DHCP</code>): Dynamic Host Configuration Protocol (automatische IP-Konfiguration / DHCPv4 / DHCPv6).\n</li></ul>\n</li><li><strong>Relationen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Beziehungstyp:</strong> Baumförmige 1:n-Dekomposition.\n</li><li><strong>Kanten-Semantik:</strong> Alle Kanten enden am Kindknoten mit einem <strong>ungefüllten Kreis (Hollow Circle)</strong>. Dies kennzeichnet normativ <strong>optionale Sub-Features</strong> (Kardinalität <code>[0..1]</code> je Zweig).\n</li><li><strong>Constraint-Ebene:</strong> Auf rein syntaktischer Ebene des Baums existieren keine zwingenden Exklusivitäten (kein XOR/OR-Bogen); semantisch gelten jedoch Protokollabhängigkeiten (z. B. zwingende Auswahl mindestens eines Network Layers <code>IP_V4</code> oder <code>IP_V6</code>; Abhängigkeit von <code>DHCP</code> von <code>UDP</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statische Variabilitätsarchitektur):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm beschreibt keinen Kontrollfluss, keine PDU-Routen und keine Laufzeit-Zustandsübergänge.\n</li><li>Es modelliert die funktionale Struktur zur Spezifikations-, Ableitungs- und Konfigurationszeit (Design-Time Variability).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- und Generierungszeit (BSW / Platform Stacks):</strong>\n<ul class=\"fig-list\"><li><strong>Classic Platform (CP):</strong> Die Selektion der Sub-Features steuert die BSW-Codegenerierung und Pre-Compile-Schalter des BSW-Moduls <code>TcpIp</code> (SWS_TCPIP) sowie übergeordneter Module (<code>SoAd</code>, <code>DoIP</code>, <code>Sd</code>). Nicht selektierte Features (z. B. <code>FO_TR_FEAT_00174</code> TCP bei reiner UDP-Broadcast-/SOME/IP-Nutzung oder <code>FO_TR_FEAT_00176</code> IPSec) werden über Schalter wie <code>TCPIP_TCP_ENABLED == STD_OFF</code> komplett aus dem Binary entfernt.\n</li><li><strong>Adaptive Platform (AP):</strong> Definiert Plattformanforderungen an den zugrundeliegenden POSIX-Kernel (z. B. Linux Network Subsystem, XFRM/IPSec-Support, Socket-Domänen <code>AF_INET</code>/<code>AF_INET6</code>) sowie System-Dienste (<code>systemd-networkd</code>, DHCP-Clients).\n</li></ul>\n</li><li><strong>Ressourcenallokation &amp; Safety/Security:</strong>\n<ul class=\"fig-list\"><li>Jedes optionale Feature bindet signifikant RAM/ROM (TCP-Send/Receive-Buffer, Reassembly-Buffer, IPSec-Security-Associations). Das Feature-Modell dient als normative Referenz zur Reduktion der Angriffsfläche (Attack Surface Reduction) und zur Einhaltung strenger Speichergrenzen im Steuergerät.\n</li></ul>\n</li><li><strong>Traceability:</strong>\n<ul class=\"fig-list\"><li>Die IDs (<code>FO_TR_FEAT_*</code>) sind bindende Tracing-Anker für Lastenhefte, Konformitätstests (Conformance Testing) und Release-Verifikationen gegen R24-11.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-d0eaca1fecf93878", "to": "FIG-c70e981e2269b518", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
